package oop.construtores.estudando.domain;public class Anime {    private String name;    private String type;    private String gender;    private int espisodes;    public Anime(String name, String type, String gender, int episodes){        this.name = name;        this.type = type;        this.gender = gender;        this.espisodes = episodes;    }    public void imprimir () {        System.out.println(this.name);        System.out.println(this.type);        System.out.println(this.gender);        System.out.println(this.espisodes);    }    public String getName() {        return this.name;    }    public String getType() {        return this.type;    }    public String getGender() {        return this.gender;    }    public int getEspisodes() {        return this.espisodes;    }}